<script setup>
import { computed, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import DataTable from 'primevue/datatable';
import Column from 'primevue/column';
import Dropdown from 'primevue/dropdown';
import InputText from 'primevue/inputtext';
import InputNumber from 'primevue/inputnumber';
import Tag from 'primevue/tag';
import Tooltip from 'primevue/tooltip';
import Paginator from 'primevue/paginator';
import AdWizard from '../components/AdWizard.vue';
import { adService, bankService, locationService } from '../services';
import { useUserAds } from '../stores/useUserAds';
import { createLogger, logException } from '../utils/logger';

const logger = createLogger('MyAdsView');
const router = useRouter();
const adsStore = useUserAds();
const currentPage = ref(1);
const totalRecords = ref(0);
const rowsPerPage = 10;
const notice = ref('');
const editingAd = ref(null);
const deletingAd = ref(null);
const showFilters = ref(true);
const banks = ref([]);
const provinces = ref([]);
const selectedBankId = ref('');
const emptyFilters = () => ({ search: '', type: '', status: '', min_amount: '', max_amount: '', min_price: '', max_price: '', province_id: '', location_id: '' });
const draftFilters = ref(emptyFilters());
const appliedFilters = ref(emptyFilters());
const typeOptions = [{ label: 'همه انواع', value: '' }, { label: 'واگذاری امتیاز', value: 'supply' }, { label: 'تقاضای خرید', value: 'demand' }];
const statusOptions = [{ label: 'همه وضعیت‌ها', value: '' }, { label: 'منتشر شده', value: 'published' }, { label: 'در انتظار تایید', value: 'pending_approval' }, { label: 'رد شده', value: 'rejected' }, { label: 'واگذار شده', value: 'handed_over' }, { label: 'منقضی شده', value: 'expired' }];
const statusText = (status) => ({ published: 'منتشر شده', pending_approval: 'در انتظار بررسی', rejected: 'رد شده', expired: 'منقضی شده', handed_over: 'واگذار شده' }[status] || 'نامشخص');
const statusSeverity = (status) => ({ published: 'success', pending_approval: 'warn', rejected: 'danger', expired: 'secondary', handed_over: 'info' }[status] || 'secondary');
const formatMoney = (value) => `${new Intl.NumberFormat('fa-IR').format(Number(value || 0))} تومان`;
const bankLogoPath = (bank) => {
    if (bank.logo_path) return bank.logo_path;
    const name = bank.name || '';
    if (name.includes('رسالت')) return '/images/banks/resalat.svg';
    if (name.includes('ملی')) return '/images/banks/melli.svg';
    if (name.includes('کشاورزی')) return '/images/banks/keshavarzi.svg';
    if (name.includes('صادرات')) return '/images/banks/saderat.svg';
    if (name.includes('مهر')) return '/images/banks/mehr-iran.svg';
    if (name.includes('مسکن')) return '/images/banks/maskan.svg';
    if (name.includes('تجارت')) return '/images/banks/tejarat.svg';
    if (name.includes('سپه')) return '/images/banks/sepah.svg';
    return '';
};
const provinceOptions = computed(() => [{ id: '', name: 'همه استان‌ها' }, ...provinces.value]);
const selectedProvince = computed(() => provinces.value.find((province) => Number(province.id) === Number(draftFilters.value.province_id)));
const cityOptions = computed(() => [{ id: '', name: 'همه شهرها' }, ...(selectedProvince.value?.children || [])]);
const quickBanks = computed(() => [{ id: '', name: 'همه بانک‌ها' }, ...banks.value]);
const requestFilters = computed(() => ({ ...appliedFilters.value, ...(selectedBankId.value ? { bank_id: selectedBankId.value } : {}) }));

async function refresh(page = currentPage.value) { await adsStore.fetchAds(requestFilters.value, page, rowsPerPage); totalRecords.value = adsStore.meta.total || 0; }
async function applyFilters() { appliedFilters.value = { ...draftFilters.value }; currentPage.value = 1; try { await refresh(1); } catch (exception) { notice.value = 'دریافت آگهی‌ها با خطا مواجه شد.'; logger.error('applyFilters', 'Advertisement filters failed', logException(exception)); } }
async function clearFilters() { draftFilters.value = emptyFilters(); selectedBankId.value = ''; await applyFilters(); }
async function selectBank(bankId) { selectedBankId.value = bankId; currentPage.value = 1; try { await refresh(1); } catch (exception) { notice.value = 'فیلتر بانک اعمال نشد.'; logger.error('selectBank', 'Bank filter failed', logException(exception)); } }
async function onPageChange(event) { currentPage.value = event.page + 1; window.scrollTo({ top: 0, behavior: 'smooth' }); try { await refresh(currentPage.value); } catch (exception) { notice.value = 'دریافت صفحه آگهی‌ها با خطا مواجه شد.'; } }
function onProvinceChange() { draftFilters.value.location_id = ''; }
function openCreate() { editingAd.value = {}; }
function viewAd(ad) { router.push({ name: 'advertisement.detail', params: { id: ad.id } }); }
function viewAdInNewTab(ad) { const url = router.resolve({ name: 'advertisement.detail', params: { id: ad.id } }).href; window.open(url, '_blank', 'noopener,noreferrer'); }
function editAd(ad) { editingAd.value = ad; }
async function markTransferred(ad) { try { await adService.toggleStatus(ad.id, 'handed_over'); notice.value = 'آگهی به وضعیت واگذار شده تغییر کرد.'; await refresh(); } catch (exception) { notice.value = 'تغییر وضعیت آگهی انجام نشد.'; logger.error('markTransferred', 'Status change failed', logException(exception)); } }
async function removeAd() { if (!deletingAd.value) return; try { await adService.delete(deletingAd.value.id); notice.value = 'آگهی حذف شد.'; deletingAd.value = null; await refresh(); } catch (exception) { notice.value = 'حذف آگهی انجام نشد.'; logger.error('removeAd', 'Delete failed', logException(exception)); } }
async function loadOptions() { const [bankResponse, locationResponse] = await Promise.all([bankService.getAll(), locationService.getProvinces()]); banks.value = bankResponse.data || bankResponse; provinces.value = locationResponse.data || locationResponse; }
onMounted(async () => { try { await Promise.all([refresh(1), loadOptions()]); } catch (exception) { notice.value = 'اطلاعات آگهی‌ها دریافت نشد.'; logger.error('onMounted', 'User advertisements initialization failed', logException(exception)); } });
</script>

<template>
<section class="my-ads-view w-full max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 space-y-6" dir="rtl" aria-labelledby="my-ads-title">
    <header class="module-header"><div><span class="module-kicker">مدیریت آگهی‌ها</span><h1 id="my-ads-title">آگهی‌های من</h1><p>آگهی‌ها، وضعیت انتشار و عملکرد خود را در یک نگاه مدیریت کنید.</p></div><button class="primary-action" type="button" @click="openCreate"><i class="pi pi-plus"></i>ثبت آگهی جدید</button></header>
    <p v-if="notice" class="module-notice" role="status">{{ notice }}</p>
    <section class="quick-bank-section" aria-labelledby="quick-bank-title"><div class="section-heading"><h2 id="quick-bank-title">فیلتر سریع بانک</h2><span>بانک موردنظر را انتخاب کنید</span></div><div class="quick-bank-bar"><button v-for="bank in quickBanks" :key="bank.id || 'all'" type="button" class="bank-chip" :class="{ selected: selectedBankId === bank.id }" @click="selectBank(bank.id)"><span class="bank-logo"><img v-if="bankLogoPath(bank)" :src="bankLogoPath(bank)" :alt="`لوگوی ${bank.name}`"><i v-else class="pi pi-building"></i></span><span>{{ bank.name }}</span></button></div></section>
    <section class="filter-panel" aria-labelledby="advanced-filters-title"><header class="filter-panel__header"><div><h2 id="advanced-filters-title">فیلترهای پیشرفته</h2><span>نتایج را دقیق‌تر پیدا کنید</span></div><button type="button" class="filter-toggle" @click="showFilters = !showFilters"><i :class="showFilters ? 'pi pi-chevron-up' : 'pi pi-chevron-down'"></i>{{ showFilters ? 'بستن فیلترها' : 'نمایش فیلترها' }}</button></header><div v-show="showFilters" class="filter-grid"><label class="filter-field filter-field--wide"><span>جستجوی عنوان یا کد آگهی</span><span class="input-with-icon"><i class="pi pi-search"></i><InputText v-model.trim="draftFilters.search" placeholder="مثلاً: وام رسالت ۱۰۰ میلیونی یا کد ۱۲۴" /></span></label><label class="filter-field"><span>نوع آگهی</span><Dropdown v-model="draftFilters.type" :options="typeOptions" option-label="label" option-value="value" placeholder="انتخاب نوع (واگذاری یا خرید)" panel-class="!bg-white !shadow-xl !border !border-gray-150 !rounded-xl !p-1 text-sm"><template #option="slotProps"><span class="dropdown-option">{{ slotProps.option.label }}</span></template></Dropdown></label><label class="filter-field"><span>وضعیت آگهی</span><Dropdown v-model="draftFilters.status" :options="statusOptions" option-label="label" option-value="value" placeholder="همه وضعیت‌ها" panel-class="!bg-white !shadow-xl !border !border-gray-150 !rounded-xl !p-1 text-sm"><template #option="slotProps"><span class="dropdown-option">{{ slotProps.option.label }}</span></template></Dropdown></label><label class="filter-field"><span>استان</span><Dropdown v-model="draftFilters.province_id" :options="provinceOptions" option-label="name" option-value="id" placeholder="انتخاب استان" panel-class="!bg-white !shadow-xl !border !border-gray-150 !rounded-xl !p-1 text-sm" @change="onProvinceChange"><template #option="slotProps"><span class="dropdown-option">{{ slotProps.option.name }}</span></template></Dropdown></label><label class="filter-field"><span>شهر</span><Dropdown v-model="draftFilters.location_id" :options="cityOptions" option-label="name" option-value="id" placeholder="ابتدا استان را انتخاب کنید" panel-class="!bg-white !shadow-xl !border !border-gray-150 !rounded-xl !p-1 text-sm" :disabled="!draftFilters.province_id"><template #option="slotProps"><span class="dropdown-option">{{ slotProps.option.name }}</span></template></Dropdown></label><label class="filter-field"><span>حداقل مبلغ تسهیلات</span><span class="money-input"><InputNumber v-model="draftFilters.min_amount" locale="fa-IR" :use-grouping="true" placeholder="مثلاً: ۵۰,۰۰۰,۰۰۰" /><span class="money-suffix">تومان</span></span></label><label class="filter-field"><span>حداکثر مبلغ تسهیلات</span><span class="money-input"><InputNumber v-model="draftFilters.max_amount" locale="fa-IR" :use-grouping="true" placeholder="مثلاً: ۵۰۰,۰۰۰,۰۰۰" /><span class="money-suffix">تومان</span></span></label><label class="filter-field"><span>حداقل قیمت واگذاری</span><span class="money-input"><InputNumber v-model="draftFilters.min_price" locale="fa-IR" :use-grouping="true" placeholder="مثلاً: ۵,۰۰۰,۰۰۰" /><span class="money-suffix">تومان</span></span></label><label class="filter-field"><span>حداکثر قیمت واگذاری</span><span class="money-input"><InputNumber v-model="draftFilters.max_price" locale="fa-IR" :use-grouping="true" placeholder="مثلاً: ۴۰,۰۰۰,۰۰۰" /><span class="money-suffix">تومان</span></span></label><div class="filter-actions"><button type="button" class="primary-action" @click="applyFilters"><i class="pi pi-filter"></i>اعمال فیلتر</button><button type="button" class="secondary-action" @click="clearFilters"><i class="pi pi-refresh"></i>پاک‌سازی فیلترها</button></div></div></section>
    <div v-if="adsStore.loading" class="module-loading" role="status"><i class="pi pi-spin pi-spinner"></i>در حال دریافت آگهی‌ها...</div>
    <section v-else class="table-section"><div class="table-heading"><div><h2>فهرست آگهی‌ها</h2><span>{{ totalRecords }} آگهی</span></div><span class="table-page-label">صفحه {{ currentPage }} از {{ adsStore.meta.last_page || 1 }}</span></div><DataTable :value="adsStore.ads" data-key="id" striped-rows responsive-layout="scroll" class="ads-table"><Column header="# / کد آگهی" style="width:100px"><template #body="slotProps"><span class="ad-code">#{{ slotProps.data.id }}</span></template></Column><Column header="عنوان و بانک" style="min-width:240px"><template #body="slotProps"><button class="title-link" type="button" @click="viewAd(slotProps.data)">{{ slotProps.data.title }}</button><span class="table-bank">{{ slotProps.data.bank }}<small>{{ slotProps.data.bank_plan?.title || slotProps.data.plan || 'طرح نامشخص' }}</small></span></template></Column><Column header="نوع" style="width:130px"><template #body="slotProps"><span class="type-badge" :class="slotProps.data.type">{{ slotProps.data.type === 'supply' ? 'واگذاری' : 'تقاضا' }}</span></template></Column><Column header="مبالغ مالی" style="min-width:190px"><template #body="slotProps"><div class="money-cell"><span>وام <strong>{{ formatMoney(slotProps.data.loan_amount ?? slotProps.data.amount) }}</strong></span><span>واگذاری <strong>{{ formatMoney(slotProps.data.assignment_price ?? slotProps.data.price) }}</strong></span></div></template></Column><Column header="موقعیت" style="min-width:150px"><template #body="slotProps"><span class="location-cell"><i class="pi pi-map-marker"></i>{{ slotProps.data.city || 'نامشخص' }}<small>{{ slotProps.data.province }}</small></span></template></Column><Column header="وضعیت" style="width:150px"><template #body="slotProps"><span v-tooltip.top="slotProps.data.status === 'rejected' ? (slotProps.data.rejection_reason || 'علت رد ثبت نشده است') : undefined"><Tag :value="statusText(slotProps.data.status)" :severity="statusSeverity(slotProps.data.status)" /></span></template></Column><Column header="تاریخ ثبت" style="min-width:130px"><template #body="slotProps"><time class="date-cell"><i class="pi pi-calendar"></i>{{ slotProps.data.time || 'تاریخ ثبت نامشخص' }}</time></template></Column><Column header="عملیات" style="min-width:185px"><template #body="slotProps"><div class="table-actions"><button v-tooltip.top="'مشاهده در تب جدید'" type="button" @click="viewAdInNewTab(slotProps.data)"><i class="pi pi-external-link"></i></button><button v-tooltip.top="'ویرایش آگهی'" type="button" @click="editAd(slotProps.data)"><i class="pi pi-pencil"></i></button><button v-if="!['handed_over', 'expired'].includes(slotProps.data.status)" v-tooltip.top="'علامت‌گذاری واگذار شده'" type="button" @click="markTransferred(slotProps.data)"><i class="pi pi-check"></i></button><button v-tooltip.top="'حذف آگهی'" class="delete-action" type="button" @click="deletingAd = slotProps.data"><i class="pi pi-trash"></i></button></div></template></Column><template #empty><div class="module-empty"><i class="pi pi-inbox"></i><h2>آگهی‌ای با این فیلترها پیدا نشد</h2><button class="primary-action" type="button" @click="clearFilters">پاک‌سازی فیلترها</button></div></template></DataTable><Paginator v-if="totalRecords > rowsPerPage" class="ads-paginator" :rows="rowsPerPage" :total-records="totalRecords" :first="(currentPage - 1) * rowsPerPage" @page="onPageChange"><template #prevpagelinkicon><i class="pi pi-chevron-right"></i></template><template #nextpagelinkicon><i class="pi pi-chevron-left"></i></template></Paginator></section>
    <div v-if="editingAd" class="wizard-overlay"><section class="wizard-dialog" role="dialog" aria-modal="true"><header><h2>{{ editingAd.id ? 'ویرایش آگهی' : 'ثبت آگهی جدید' }}</h2><button type="button" aria-label="بستن" @click="editingAd = null"><i class="pi pi-times"></i></button></header><AdWizard :banks="banks" :provinces="provinces" :advertisement="editingAd.id ? editingAd : null" @saved="async () => { editingAd = null; notice = 'آگهی شما ثبت شد و پس از بررسی تیم مستروام منتشر خواهد شد'; await refresh(); }" @cancel="editingAd = null" /></section></div>
    <div v-if="deletingAd" class="confirm-overlay"><section class="confirm-dialog" role="alertdialog" aria-modal="true"><i class="pi pi-trash"></i><h2>حذف آگهی؟</h2><p>این آگهی از فهرست شما حذف خواهد شد.</p><footer><button type="button" class="secondary-action" @click="deletingAd = null">انصراف</button><button type="button" class="danger-action" @click="removeAd">حذف آگهی</button></footer></section></div>
</section>
</template>

<style scoped>
